mapper.update:
UPDATE ha_conversation_history
SET
    payload_json = #{payloadJson}
WHERE
    owner_key = #{ownerKey}
    AND record_type = 'MESSAGE'
    AND record_id = #{recordId}

mapper.select:
SELECT a.*
FROM ha_artifact a
JOIN (
    SELECT artifact_id, MAX(created_at) AS last_used
    FROM ha_conversation_history
    WHERE owner_key = #{ownerKey}
        AND session_id = #{sessionId}
        AND record_type = 'ARTIFACT_REFERENCE'

        AND artifact_role = 'OUTPUT'

    GROUP BY artifact_id
) h ON a.artifact_id = h.artifact_id
WHERE a.owner_key = #{ownerKey}
    AND a.status = #{readyStatus}
ORDER BY h.last_used DESC, a.artifact_id DESC
LIMIT #{limit} OFFSET #{offset}
